#!/bin/bash\n\n# Crypto Scalp Arena - Local Development Runner\n# Starts all services in separate terminal windows\n\nset -e\n\necho \"🚀 Starting Crypto Scalp Arena...\"\n\n# Check if Redis is running\nif ! command -v redis-server &> /dev/null; then\n    echo \"❌ Redis is not installed. Please install Redis first.\"\n    exit 1\nfi\n\n# Create logs directory\nmkdir -p logs\n\n# Load environment variables\nif [ -f .env ]; then\n    export $(cat .env | grep -v '#' | xargs)\nelse\n    echo \"⚠️  .env file not found. Using default values.\"\nfi\n\n# Function to run service in new terminal\nrun_service() {\n    local service_name=$1\n    local command=$2\n    \n    echo \"Starting $service_name...\"\n    \n    if command -v gnome-terminal &> /dev/null; then\n        gnome-terminal -- bash -c \"cd $(pwd) && $command; read -p 'Press enter to close...'\"\n    elif command -v xterm &> /dev/null; then\n        xterm -e \"cd $(pwd) && $command\" &\n    elif command -v open &> /dev/null; then\n        # macOS\n        open -a Terminal <<EOF\ncd $(pwd)\n$command\nEOF\n    else\n        # Fallback: run in background\n        eval \"$command &\"\n    fi\n}\n\n# Start Redis\necho \"📦 Starting Redis...\"\nredis-server --daemonize yes --logfile logs/redis.log\nsleep 2\n\n# Start Python services\necho \"🤖 Starting Python services...\"\n\n# Install dependencies if needed\nif [ ! -d \"venv\" ]; then\n    echo \"📦 Creating virtual environment...\"\n    python3 -m venv venv\n    source venv/bin/activate\n    pip install -e .\nelse\n    source venv/bin/activate\nfi\n\n# Run services\nrun_service \"Data Feed\" \"python -m src.services.data_feed\"\nsleep 2\n\nrun_service \"Arena Manager\" \"python -m src.services.arena_manager\"\nsleep 2\n\nrun_service \"Telegram Service\" \"python -m src.services.telegram_service\"\nsleep 2\n\nrun_service \"API Server\" \"python -m src.services.api_server\"\n\necho \"✅ All services started!\"\necho \"\"\necho \"📊 Dashboard: http://localhost:3000\"\necho \"🔌 API: http://localhost:8000\"\necho \"📡 WebSocket: ws://localhost:8000/ws/performance\"\necho \"\"\necho \"Press Ctrl+C to stop services\"\n\n# Keep script running\nwait\n
